<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Pobrecita Photo Gallery</title>
  <style>
    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      background: #fff8f5;
      color: #4a3b3b;
    }

    header {
      text-align: center;
      padding: 2rem 1rem;
      background: #ffe3dc;
    }

    header h1 {
      margin: 0;
      font-size: 2rem;
      color: #8b5b5b;
    }

    header p {
      margin: 0.5rem 0 0;
      font-size: 1rem;
      color: #7a5a5a;
    }

    main {
      max-width: 1200px;
      margin: 0 auto;
      padding: 2rem 1rem;
    }

    .gallery {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
      gap: 1.5rem;
    }

    .photo {
      position: relative;
      overflow: hidden;
      border-radius: 12px;
      box-shadow: 0 4px 12px rgba(139, 91, 91, 0.15);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
      background: #fff;
    }

    .photo:hover {
      transform: translateY(-4px);
      box-shadow: 0 8px 20px rgba(139, 91, 91, 0.25);
    }

    .photo img {
      width: 100%;
      height: 220px;
      object-fit: cover;
      display: block;
    }

    .photo .caption {
      padding: 0.75rem;
      font-weight: 600;
      text-align: center;
      color: #7a5a5a;
      background: #fff;
    }

    .lightbox {
      position: fixed;
      inset: 0;
      display: none;
      align-items: center;
      justify-content: center;
      background: rgba(40, 25, 25, 0.92);
      z-index: 1000;
      padding: 1rem;
    }

    .lightbox.active {
      display: flex;
    }

    .lightbox-content {
      position: relative;
      max-width: 90vw;
      max-height: 90vh;
      display: flex;
      flex-direction: column;
      align-items: center;
    }

    .lightbox img {
      max-width: 100%;
      max-height: 80vh;
      border-radius: 8px;
      box-shadow: 0 8px 30px rgba(0, 0, 0, 0.4);
    }

    .lightbox-info {
      margin-top: 1rem;
      text-align: center;
      color: #fff8f5;
    }

    .lightbox-info h2 {
      margin: 0;
      font-size: 1.25rem;
    }

    .lightbox-info p {
      margin: 0.25rem 0 0;
      font-size: 0.95rem;
      opacity: 0.85;
    }

    .btn {
      position: absolute;
      background: rgba(255, 255, 255, 0.15);
      border: none;
      color: #fff;
      font-size: 2rem;
      width: 44px;
      height: 44px;
      border-radius: 50%;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 0.2s ease;
      user-select: none;
    }

    .btn:hover {
      background: rgba(255, 255, 255, 0.3);
    }

    .close {
      top: 1rem;
      right: 1rem;
      font-size: 1.5rem;
    }

    .prev {
      left: 1rem;
      top: 50%;
      transform: translateY(-50%);
    }

    .next {
      right: 1rem;
      top: 50%;
      transform: translateY(-50%);
    }

    .counter {
      position: absolute;
      top: 1rem;
      left: 1rem;
      color: #fff;
      background: rgba(255, 255, 255, 0.15);
      padding: 0.3rem 0.7rem;
      border-radius: 20px;
      font-size: 0.9rem;
    }

    @media (max-width: 600px) {
      .prev, .next {
        display: none;
      }

      .lightbox img {
        max-height: 70vh;
      }
    }
  </style>
</head>
<body>
  <header>
    <h1>Pobrecita</h1>
    <p>A little self-contained photo gallery</p>
  </header>

  <main>
    <div id="gallery" class="gallery"></div>
  </main>

  <div id="lightbox" class="lightbox">
    <div class="lightbox-content">
      <span id="counter" class="counter"></span>
      <button id="closeBtn" class="btn close" aria-label="Close">&times;</button>
      <button id="prevBtn" class="btn prev" aria-label="Previous">&#10094;</button>
      <button id="nextBtn" class="btn next" aria-label="Next">&#10095;</button>
      <img id="lightboxImg" src="" alt="" />
      <div class="lightbox-info">
        <h2 id="lightboxTitle"></h2>
        <p id="lightboxDesc"></p>
      </div>
    </div>
  </div>

  <script>
    const photos = [
      { title: "Sunset Dreams", desc: "Warm colors fading into the horizon.", color: "#ff9a8b" },
      { title: "Morning Mist", desc: "A quiet start to the day.", color: "#a8d8ea" },
      { title: "Little Flower", desc: "Delicate petals in soft light.", color: "#f8b195" },
      { title: "Ocean Breeze", desc: "Salt air and endless waves.", color: "#6a8caf" },
      { title: "Cozy Corner", desc: "A safe place to rest.", color: "#d4a5a5" },
      { title: "Golden Hour", desc: "Everything glows just before dusk.", color: "#f6d365" },
      { title: "Mountain Path", desc: "Winding roads and fresh air.", color: "#8fc1a9" },
      { title: "Starlight", desc: "Tiny lights in a vast sky.", color: "#574b90" },
      { title: "Sweet Treat", desc: "A little joy on a plate.", color: "#e89da0" }
    ];

    const gallery = document.getElementById("gallery");
    const lightbox = document.getElementById("lightbox");
    const lightboxImg = document.getElementById("lightboxImg");
    const lightboxTitle = document.getElementById("lightboxTitle");
    const lightboxDesc = document.getElementById("lightboxDesc");
    const counter = document.getElementById("counter");

    let currentIndex = 0;

    function makeSvg(color, label) {
      const text = encodeURIComponent(label);
      return `data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='400' height='300'><rect width='400' height='300' fill='${color}'/><text x='50%25' y='50%25' dominant-baseline='middle' text-anchor='middle' font-family='sans-serif' font-size='24' fill='rgba(255,255,255,0.8)'>${text}</text></svg>`;
    }

    function renderGallery() {
      photos.forEach((photo, index) => {
        const card = document.createElement("div");
        card.className = "photo";
        card.setAttribute("role", "button");
        card.setAttribute("aria-label", `View ${photo.title}`);

        const img = document.createElement("img");
        img.src = makeSvg(photo.color, photo.title);
        img.alt = photo.title;

        const caption = document.createElement("div");
        caption.className = "caption";
        caption.textContent = photo.title;

        card.appendChild(img);
        card.appendChild(caption);
        card.addEventListener("click", () => openLightbox(index));
        gallery.appendChild(card);
      });
    }

    function openLightbox(index) {
      currentIndex = index;
      updateLightbox();
      lightbox.classList.add("active");
      document.body.style.overflow = "hidden";
    }

    function closeLightbox() {
      lightbox.classList.remove("active");
      document.body.style.overflow = "";
    }

    function updateLightbox() {
      const photo = photos[currentIndex];
      lightboxImg.src = makeSvg(photo.color, photo.title);
      lightboxImg.alt = photo.title;
      lightboxTitle.textContent = photo.title;
      lightboxDesc.textContent = photo.desc;
      counter.textContent = `${currentIndex + 1} / ${photos.length}`;
    }

    function showNext(e) {
      e.stopPropagation();
      currentIndex = (currentIndex + 1) % photos.length;
      updateLightbox();
    }

    function showPrev(e) {
      e.stopPropagation();
      currentIndex = (currentIndex - 1 + photos.length) % photos.length;
      updateLightbox();
    }

    document.getElementById("closeBtn").addEventListener("click", closeLightbox);
    document.getElementById("nextBtn").addEventListener("click", showNext);
    document.getElementById("prevBtn").addEventListener("click", showPrev);

    lightbox.addEventListener("click", (e) => {
      if (e.target === lightbox) closeLightbox();
    });

    document.addEventListener("keydown", (e) => {
      if (!lightbox.classList.contains("active")) return;
      if (e.key === "Escape") closeLightbox();
      if (e.key === "ArrowRight") showNext(e);
      if (e.key === "ArrowLeft") showPrev(e);
    });

    renderGallery();
  </script>
</body>
</html>
